Вот TypeScript-вариант `calculateDr` с учётом родительских зон:  

```ts
import { ArmorHitLocationStats, HitLocation, ArmorMaterial } from '../utils';

export class EquipmentEntity {
  coverage: number;
  material: ArmorMaterial;
  layers: number;
  dr: number = 0;

  constructor({
    coverage = 0,
    material,
    layers = 1,
  }: {
    coverage?: number;
    material: ArmorMaterial;
    layers?: number;
  }) {
    this.coverage = coverage;
    this.material = material;
    this.layers = layers;
    this.calculateDr();
  }

  /**
   * Рассчитывает DR брони с учётом покрытия и родительских зон
   * Если DR разных зон различается, кидает ошибку
   */
  calculateDr(): this {
    if (!this.material || !this.coverage) {
      this.dr = 0;
      return this;
    }

    let drValue: number | null = null;

    for (const zoneKeyStr of Object.keys(ArmorHitLocationStats)) {
      const zoneBit = Number(zoneKeyStr);
      const zoneStats = ArmorHitLocationStats[zoneBit];

      // Игнорируем дочерние зоны, если родитель покрыт
      if (zoneStats.parentZone && (this.coverage & zoneStats.parentZone) !== 0) {
        continue;
      }

      if ((this.coverage & zoneBit) !== 0) {
        const zoneDr = this.material.drPerLayer * this.layers;

        if (drValue === null) {
          drValue = zoneDr;
        } else if (drValue !== zoneDr) {
          throw new Error(
            `Inconsistent DR detected: zone ${zoneBit} has DR ${zoneDr}, expected ${drValue}`
          );
        }
      }
    }

    this.dr = drValue ?? 0;
    return this;
  }
}
```

**Что поменялось:**  

- DR **не суммируется**, а проверяется на равенство.  
- Используется `drValue` как эталон. Если находим зону с другим DR, кидаем `Error`.  
- Игнорируются дочерние зоны, покрытые родительской зоной.  

